function chips(items,action,selected){return items.map(n=>`<button class="chip ${n===selected?'active':''}" data-action="${action}" data-value="${n}" aria-pressed="${n===selected}">${n}</button>`).join('')}
function pageTop(eye,title,desc,action=''){return `<section class="wrap page-top"><div class="breadcrumb"><a href="#/">Accueil</a><span>/</span><span>${eye}</span></div><div class="page-title-row"><div><span class="eyebrow">${eye}</span><h1>${title}</h1><p class="lead">${desc}</p></div>${action}</div></section>`}
function serviceLink(s,cls='service-card'){return `<a ${s.to.startsWith('#')?`href="${s.to}"`:`href="#/services" data-action="${s.to==='council'?'council':'service-detail'}" data-id="${s.id}"`} class="${cls}">${icon(s.icon)}<h3>${s.title}</h3><p>${s.desc}</p><span class="card-bottom">${s.category}${icon('arrow-up-right')}</span></a>`}
function eventCard(e){return `<article class="event-card"><button class="event-photo" data-action="event" data-id="${e.id}" aria-label="Découvrir ${e.title}">${img(e.image)}<span class="date-badge"><strong>${e.day}</strong>${e.month===10?'OCT.':'NOV.'}</span></button><div class="event-info"><span class="eyebrow">${e.category} · exemple de rendez-vous</span><h3><button data-action="event" data-id="${e.id}" style="padding:0;text-align:left;letter-spacing:inherit;line-height:inherit;font-weight:inherit">${e.title}</button></h3><div class="event-info-bottom"><p>${icon('pin')}${e.place}</p><button class="save-event" data-action="save-event" data-id="${e.id}" aria-label="${saved.includes(e.id)?'Retirer':'Enregistrer'} ${e.title}" aria-pressed="${saved.includes(e.id)}">${icon('bookmark')}</button></div></div></article>`}
function galleryTile(n){return `<button class="gallery-tile" data-action="gallery" data-id="${n}" aria-label="Voir la photo : ${photos[n].label}">${img(n)}<span>${photos[n].label}${icon('arrow-up-right')}</span></button>`}
function servicesView(){return `${pageTop('Au quotidien','De quoi avez-vous besoin ?','Partez de votre besoin. Nous vous aidons à trouver le bon service, quel que soit celui qui s’en occupe.')}<section class="wrap page-content"><label class="page-search">${icon('search')}<input id="service-search" type="search" placeholder="Un besoin, une démarche, un mot-clé…" aria-label="Filtrer les services" value="${esc(state.serviceQuery)}"></label><div class="filter-row" id="service-filters">${chips(['Tout','Démarches','Famille','Loisirs','Cadre de vie','Participation'],'service-filter',state.serviceFilter)}</div><a class="directory-banner" href="#/services"><span>${icon('grid')}Tous les sites & services en ligne</span><span>Portail famille, médiathèques, billetterie, open data… ${icon('arrow-right')}</span></a><div class="profile-row"><span>JE SUIS…</span>${['Parent','Nouvel arrivant','Senior','Une association'].map(x=>`<button class="chip" data-action="profile" data-value="${x}">${x}</button>`).join('')}</div><p id="services-count" class="eyebrow" role="status" style="margin-bottom:18px"></p><div class="service-grid" id="services-list"></div><div class="subtle-box">${icon('phone')}<p><strong>Vous préférez échanger avec quelqu’un ?</strong><br>Les équipes de la mairie vous accompagnent dans vos démarches.</p><a class="button outline small" href="#/contact">Nous contacter ${icon('arrow-right')}</a></div></section>`}
function participationView(){return `${pageTop('Participer','Projets et participation','Comprendre les projets, suivre la vie de son quartier et prendre part aux réflexions de la Ville.')}<section class="wrap page-content"><div class="project-grid"><article class="project-card">${img(5)}<div><span class="tag">Meudon 2040</span><h3>Meudon 2040</h3><p>Retrouvez le projet Meudon 2040 et les informations publiées par la Ville. La maquette propose une entrée claire dans ce dossier.</p><button class="text-link" data-action="project" data-id="vision">Comprendre le projet ${icon('arrow-right')}</button></div></article><article class="project-card">${img(2)}<div><span class="tag">Énergie & cadre de vie</span><h3>La géothermie à Meudon-la-Forêt</h3><p>La géothermie à Meudon-la-Forêt : accéder au dossier officiel, identifier les étapes et les informations utiles.</p><button class="text-link" data-action="project" data-id="geo">Explorer le dossier ${icon('arrow-right')}</button></div></article></div><div class="section-header" style="margin-top:65px"><div><span class="eyebrow">CONSEILS DE QUARTIER</span><h2>Les conseils de quartier</h2></div><button class="text-link" data-action="council">Les conseils de quartier ${icon('arrow-right')}</button></div><div class="participation-steps"><div><strong>01 / JE M’INFORME</strong><h3>Le sujet, en clair.</h3><p>Une présentation accessible des objectifs, du contexte et des documents disponibles.</p></div><div><strong>02 / J’ÉCHANGE</strong><h3>Une place pour chacun.</h3><p>Les bons points de contact pour partager une idée et participer à la vie locale.</p></div><div><strong>03 / JE SUIS LES SUITES</strong><h3>Le fil de la discussion.</h3><p>Un accès aux sujets des conseils de quartier et aux comptes rendus publiés.</p></div></div><div class="subtle-box">${icon('users')}<p><strong>Retrouvez les démarches de participation existantes.</strong><br>Les contributions de cette maquette ne sont pas transmises à la Ville.</p><a href="https://jeparticipe.meudon.fr/" target="_blank" rel="noopener" class="button primary small">Je participe à Meudon ${icon('external')}</a></div></section>`}
function contactView(){return `${pageTop('Contact','La ville à votre écoute.','Une question, un besoin d’accompagnement : retrouvez les accueils de la mairie.')}<section class="wrap page-content"><div class="contact-layout"><article class="contact-box"><span class="eyebrow">MEUDON CENTRE</span><h2>Hôtel de Ville</h2><p>6 avenue Le Corbeiller<br>92190 Meudon</p><a class="button primary" href="tel:+33141148000">${icon('phone')}01 41 14 80 00</a><dl><dt>Lundi, mardi, mercredi et vendredi</dt><dd>8h30–12h et 13h30–17h30</dd><dt>Jeudi et samedi</dt><dd>8h30–12h · fermé l’après-midi</dd></dl></article><article class="contact-box"><span class="eyebrow">MEUDON-LA-FORÊT</span><h2>Mairie annexe</h2><p>Place Henry-Wolf<br>92360 Meudon-la-Forêt</p><a class="button primary" href="tel:+33141281940">${icon('phone')}01 41 28 19 40</a><dl><dt>Lundi, mardi, mercredi et vendredi</dt><dd>8h30–12h et 13h30–17h30</dd><dt>Jeudi / samedi</dt><dd>Jeudi : 8h30–12h · samedi : 9h–12h</dd></dl></article></div><div class="subtle-box">${icon('clock')}<p>Horaires repris du site officiel, consulté le 11 octobre 2026. Accueil sans rendez-vous ; démarches sur rendez-vous. Vérifiez les éventuelles fermetures exceptionnelles avant votre venue.</p><a class="text-link" href="${official.contact}" target="_blank" rel="noopener">Page officielle ${icon('external')}</a></div></section>`}
function wizardContent(){if(state.wizardStep===1)return `<span class="eyebrow">ÉTAPE 1 SUR 3</span><h2>Quel âge a votre enfant ?</h2><p>Ce choix nous aide à vous orienter. Aucune donnée n’est envoyée.</p><div class="choice-grid">${['Moins de 3 ans','3 à 5 ans','6 à 10 ans','11 ans et plus'].map(a=>`<button class="choice ${state.age===a?'selected':''}" data-action="age" data-value="${a}" aria-pressed="${state.age===a}">${icon('child')}<strong>${a}</strong></button>`).join('')}</div><div class="wizard-footer"><a class="text-link" href="#/services">Tous les services</a><button class="button primary" data-action="wizard-next" ${!state.age?'disabled':''}>Continuer ${icon('arrow-right')}</button></div>`;
if(state.wizardStep===2)return `<span class="eyebrow">ÉTAPE 2 SUR 3 · ${state.age}</span><h2>Quelle est votre envie ?</h2><p>Les démarches municipales et les activités associatives se rejoignent ici.</p><div class="choice-grid">${[{name:'École & périscolaire',icon:'book',sub:'École, cantine, accueils'},{name:'Sport',icon:'sports',sub:'École des sports et clubs'},{name:'Culture & loisirs',icon:'sun',sub:'Découverte, création, activités'},{name:'Petite enfance',icon:'child',sub:'Information sur les modes d’accueil'}].map(a=>`<button class="choice ${state.activity===a.name?'selected':''}" data-action="activity" data-value="${a.name}" aria-pressed="${state.activity===a.name}">${icon(a.icon)}<strong>${a.name}</strong><small>${a.sub}</small></button>`).join('')}</div><div class="wizard-footer"><button class="text-link" data-action="wizard-back">${icon('arrow-left')} Retour</button><button class="button primary" data-action="wizard-next" ${!state.activity?'disabled':''}>Voir mon parcours ${icon('arrow-right')}</button></div>`;
const sport=state.activity==='Sport',culture=state.activity==='Culture & loisirs',small=state.activity==='Petite enfance';const dest=sport?official.sport:culture?official.association:small?'https://www.meudon.fr/mon-quotidien/enfance-et-jeunesse/petite-enfance/':official.family;
return `<span class="eyebrow">VOTRE POINT DE DÉPART</span><h2>${sport?'Du mouvement et des découvertes.':culture?'Une nouvelle passion à explorer.':small?'Un accueil à trouver ensemble.':'L’école et les loisirs, en lien.'}</h2><p>${state.age} · ${state.activity}</p><ul class="checklist"><li>${icon('check')}Consulter les activités et conditions d’accueil</li><li>${icon('check')}Vérifier les âges et les périodes d’inscription</li><li>${icon('check')}Préparer les documents demandés par le service</li></ul><a class="button primary" href="${dest}" target="_blank" rel="noopener">${sport?'École municipale des sports':culture?'Explorer les associations':small?'Informations petite enfance':'Ouvrir le portail famille'} ${icon('external')}</a><p class="result-note">Vous accédez au service officiel existant. Ce prototype ne réalise aucune inscription et ne vérifie pas l’éligibilité. Les pièces et les dates sont à confirmer auprès du service.</p><div class="wizard-footer"><button class="text-link" data-action="wizard-back">${icon('arrow-left')} Modifier mon choix</button><a class="text-link" href="#/contact">Besoin d’aide ?</a></div>`}
// Navigation, services municipaux et réseaux officiels.
const directoryState={category:'Tous',query:'',savedOnly:false,sort:'usage'};
let serviceFavorites=[];try{serviceFavorites=JSON.parse(localStorage.getItem('meudon-service-favorites')||'[]')}catch{}if(!Array.isArray(serviceFavorites))serviceFavorites=[];serviceFavorites=[...new Set(serviceFavorites.filter(id=>[...municipalNetwork,...civicServices].some(s=>s.id===id)))];
const directoryCategories=['Tous','Démarches','Famille','Culture & sport','Cadre de vie','Solidarité & santé','Participation','La mairie','Données publiques'];
const menuGroups={
quotidien:{title:'Démarches & services',intro:'Une entrée commune pour vos démarches et vos services.',image:5,route:'/services',link:'Tous les services',items:[['Papiers d’identité','Préparer un rendez-vous','file','#/service/identite'],['Actes d’état civil','Naissance, mariage, décès','file','#/service/actes'],['Déchets & propreté','Collecte et signalement','leaf','#/service/dechets'],['Stationnement','Règles, zones et parkings','map','#/service/stationnement'],['Solidarité & santé','Aides et accompagnement','heart','#/services?categorie=Solidarité%20%26%20santé'],['Urbanisme','Demandes et dossiers','building','#/service/urbanisme']]},
famille:{title:'Enfance & famille',intro:'Les démarches utiles selon l’âge de votre enfant.',image:6,route:'/famille',link:'Tous les services famille',items:[['Inscription en crèche','Les modes d’accueil','child','#/service/creche'],['Inscription scolaire','Préparer la démarche','book','#/service/inscription-scolaire'],['Cantine & compte famille','Réservations et paiements','file','#/service/famille'],['Accueil de loisirs','Inscriptions périscolaires','child','#/service/periscolaire'],['Activités régulières','Sport et culture','sports','#/activites']]},
sortir:{title:'Sorties & activités',intro:'Choisir une sortie ou une pratique régulière.',image:1,route:'/agenda',link:'Tout l’agenda',items:[['Agenda des sorties','Événements municipaux et associatifs','calendar','#/agenda'],['Activités et inscriptions','Cours, sport et culture','sports','#/activites'],['Médiathèques','Livres et compte lecteur','book','#/service/mediatheques'],['Spectacles','Billetterie culturelle','calendar','#/service/culture'],['Musée d’art et d’histoire','Préparer sa visite','building','#/service/musee'],['Albums photo','Patrimoine et paysages','camera','#/galerie']]},
associations:{title:'Associations',intro:'Trouver un collectif ou faire connaître ses initiatives.',image:3,route:'/associations',link:'Trouver une association',items:[['Annuaire des associations','Nom, activité et domaine','users','#/associations'],['Bénévolat & solidarité','S’engager près de chez soi','heart','#/associations?categorie=Solidarité'],['Événements associatifs','Les rendez-vous dans l’agenda','calendar','#/agenda?organisateur=association'],['Espace responsables','Ressources et proposition d’événement','file','#/espace-associations']]},
quartiers:{title:'Mon quartier',intro:'Les lieux, les projets et les échanges de proximité.',image:4,route:'/quartiers',link:'Tous les quartiers',items:districts.map((d,i)=>[d.name,'Lieux, dossiers et conseil de quartier','pin',`#/quartiers?quartier=${i}`])},
ville:{title:'La Ville & la mairie',intro:'Découvrir Meudon et retrouver vos interlocuteurs.',image:0,route:'/mairie',link:'Toute la vie municipale',items:[['Présentation de Meudon','Nature, patrimoine et équipements','compass','#/decouvrir'],['Horaires et contacts','Les accueils de la mairie','phone','#/contact'],['Les élus','Maire et délégations','users','#/service/elus'],['Conseil municipal','Décisions et publications','file','#/service/conseil-municipal'],['Projets & participation','Dossiers et contributions','compass','#/participer'],['Actualités','Les informations de la Ville','file','#/service/actualites'],['Données publiques','Meudon et GPSO','grid','#/services?categorie=Données%20publiques']]}
};
function externalAttrs(){return 'target="_blank" rel="noopener noreferrer"'}
function menuLink(item){const [title,desc,ic,to]=item;let attrs='';if(to.startsWith('@')){const service=portalById(to.slice(1));attrs=`href="${service?.url||official.services}" ${externalAttrs()}`;}else if(to.startsWith('!'))attrs=`href="#/quartiers" data-action="choose-district" data-id="${to.slice(1)}"`;else attrs=`href="${to}"`;return `<a ${attrs} class="mega-link">${icon(ic)}<span><strong>${title}</strong><small>${desc}</small></span>${icon(to.startsWith('@')?'external':'arrow-right')}</a>`}
function megaMenu(key){const panel=$('#mega-panel'),trigger=$(`[data-action=mega][data-menu=${key}]`);if(!panel.hidden&&panel.dataset.menu===key){closeMega(true);return}closeMega();const m=menuGroups[key];panel.dataset.menu=key;panel.innerHTML=`<div class="mega-intro"><span class="eyebrow">MEUDON À VOTRE SERVICE</span><h2>${m.title}</h2><p>${m.intro}</p><a href="#${m.route}" class="text-link">${m.link} ${icon('arrow-right')}</a></div><div class="mega-links">${m.items.map(menuLink).join('')}</div><a href="#${m.route}" class="mega-feature">${img(m.image)}<span>${m.title}<br><strong>${m.link} ${icon('arrow-up-right')}</strong></span></a><button class="mega-close icon-button" data-action="close-mega" aria-label="Fermer le sous-menu">${icon('x')}</button>`;panel.hidden=false;$('#nav-backdrop').style.top=$('.site-header').getBoundingClientRect().bottom+'px';$('#nav-backdrop').hidden=false;trigger.setAttribute('aria-expanded','true');hydrate(panel)}
function closeMega(returnFocus=false){const panel=$('#mega-panel');if(!panel)return;const key=panel.dataset.menu;panel.hidden=true;$('#nav-backdrop').hidden=true;$$('[data-action=mega]').forEach(b=>b.setAttribute('aria-expanded','false'));if(returnFocus&&key)$(`[data-menu=${key}]`)?.focus()}
function buildMobileMenu(){return `<div class="mobile-menu-top"><span class="eyebrow">OÙ SOUHAITEZ-VOUS ALLER ?</span><button data-action="search" class="text-link">Rechercher ${icon('search')}</button></div>${Object.entries(menuGroups).map(([key,m])=>`<details class="mobile-menu-group"><summary>${m.title}${icon('plus')}</summary><div>${m.items.map(menuLink).join('')}<a class="text-link" href="#${m.route}">${m.link} ${icon('arrow-right')}</a></div></details>`).join('')}<a class="button primary mobile-all" href="#/services">Tous les sites & services ${icon('grid')}</a><div class="mobile-utility"><a href="#/contact">Contact & horaires</a><button data-action="accessibility">Confort de lecture</button></div>`}
function serviceHub(){return `<section class="wrap portal-home section"><div class="section-header"><div><span class="eyebrow">VOS SERVICES EN LIGNE</span><h2>Vos services.<br>Au même endroit.</h2></div><div><p>Famille, culture, démarches : vos accès utiles réunis, quel que soit le service qui vous accompagne.</p><a href="#/services" class="text-link">Tous les sites & services ${icon('arrow-right')}</a></div></div><div class="portal-home-grid">${['famille','demarches','mediatheques','culture','participation','data-meudon'].map(id=>portalById(id)).filter(Boolean).map(s=>networkLink(s,true)).join('')}</div></section>`}
function saveService(id){if(!portalById(id))return;serviceFavorites=serviceFavorites.includes(id)?serviceFavorites.filter(x=>x!==id):[...serviceFavorites,id];try{localStorage.setItem('meudon-service-favorites',JSON.stringify(serviceFavorites))}catch{}if($('#directory-results')){updateDirectory();$('#favorite-services-count').textContent=serviceFavorites.length;const target=$(`[data-action=save-service][data-id=${id}]`);if(target)target.focus({preventScroll:true});else $('.directory-saved').focus({preventScroll:true})}if(currentRoute.startsWith('/service/')){const b=$('[data-action=save-service]');if(b){b.setAttribute('aria-pressed',String(serviceFavorites.includes(id)));b.innerHTML=icon('bookmark')+(serviceFavorites.includes(id)?'Retirer de mes raccourcis':'Enregistrer ce service')}}toast(serviceFavorites.includes(id)?'Service ajouté à vos raccourcis sur cet appareil.':'Service retiré de vos raccourcis.')}
function portalDetail(id){const s=portalById(id);if(!s)return;contentDialog(s.category,s.title,`<p>${s.desc}</p><dl class="portal-facts"><div><dt>Le service</dt><dd>${s.brand}</dd></div><div><dt>Pour qui ?</dt><dd>${s.audience}</dd></div><div><dt>Le bon réflexe</dt><dd>${s.note}</dd></div></dl><a class="button primary" href="${s.url}" ${externalAttrs()}>Accéder au service ${icon('external')}</a><p class="form-note">${s.fallback?'Nous vous orientons vers la page officielle qui présente les accès disponibles.':'Le service s’ouvre dans un nouvel onglet, sur '+s.domain+'.'} Les conditions d’accès sont celles du service concerné.</p><a class="text-link" href="#/services" data-action="close-link">Tous les services ${icon('arrow-right')}</a>`)}
function counterMarkup(f){return `<article class="city-figure"><span class="eyebrow">${f.eyebrow}</span><div class="figure-value"><span class="sr-only">${f.display} ${f.label}</span><span class="counter-face" aria-hidden="true" data-counter="${f.value}" data-display="${f.display}">${f.display}</span>${f.unit?`<span class="figure-unit" aria-hidden="true">${f.unit}</span>`:''}</div><h3 aria-hidden="true">${f.label}</h3><a href="${f.source}" ${externalAttrs()} class="figure-source">${f.sourceLabel} ${icon('external')}</a></article>`}
function cityStats(){return `<section class="city-figures"><div class="wrap"><div class="figure-intro"><span class="eyebrow">MEUDON EN QUELQUES REPÈRES</span><span>Population, quartiers et espaces verts</span></div><div class="figures-grid">${cityFigures.map(counterMarkup).join('')}</div><p class="figure-note">Des chiffres datés et sourcés. Le compteur illustre ces données, il ne s’agit pas d’une mesure en temps réel.</p></div></section>`}
let counterObserver;const counterFrames=new Map();function finishCounters(){if(counterObserver)counterObserver.disconnect();counterFrames.forEach(frame=>cancelAnimationFrame(frame));counterFrames.clear();$$('[data-counter]').forEach(el=>{el.textContent=el.dataset.display;el.classList.remove('is-counting')})}
function animateCounters(){finishCounters();if(preferences.motion||matchMedia('(prefers-reduced-motion: reduce)').matches||!('IntersectionObserver' in window))return;counterObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(!entry.isIntersecting)return;const el=entry.target;counterObserver.unobserve(el);const value=Number(el.dataset.counter),duration=value>100?1250:950;let start;el.classList.add('is-counting');function tick(t){if(!el.isConnected||preferences.motion){el.textContent=el.dataset.display;counterFrames.delete(el);return}if(!start)start=t;const p=Math.min(1,(t-start)/duration);const ease=1-Math.pow(1-p,4);el.textContent=Math.round(value*ease).toLocaleString('fr-FR');if(p<1)counterFrames.set(el,requestAnimationFrame(tick));else{el.textContent=el.dataset.display;el.classList.remove('is-counting');counterFrames.delete(el)}}counterFrames.set(el,requestAnimationFrame(tick))})},{threshold:.65});$$('[data-counter]').forEach(el=>counterObserver.observe(el))}
function socialLinks(style=''){return socialChannels.map(c=>`<a href="${c.url}" ${externalAttrs()} class="social-link ${style}" aria-label="${c.name} officiel de la Ville de Meudon — nouvel onglet">${icon(c.icon)}<span>${c.name}</span>${icon('external')}</a>`).join('')}
function socialSection(){return `<section class="social-section wrap section"><div class="social-editorial"><div class="social-photo">${img(5)}<span>MEUDON, AU FIL DES JOURS</span></div><div class="social-copy"><span class="eyebrow">ON GARDE LE LIEN</span><h2>Votre ville.<br>Dans votre fil.</h2><p>Les nouvelles, les images, les rendez-vous : retrouvez Meudon sur ses réseaux officiels.</p><div class="social-inline">${socialChannels.slice(0,3).map(c=>`<a href="${c.url}" ${externalAttrs()} aria-label="${c.name} officiel de Meudon, nouvel onglet">${icon(c.icon)}${c.name} ${icon('arrow-up-right')}</a>`).join('')}</div><a href="#/reseaux" class="text-link">Tous les réseaux de la Ville ${icon('arrow-right')}</a></div></div></section>`}
function socialsView(){return `${pageTop('Les réseaux de la Ville','Meudon, au fil des jours.','Photos, informations pratiques, vidéos et vie municipale. Choisissez les comptes officiels que vous souhaitez suivre.')}<section class="wrap page-content"><div class="social-channel-grid">${socialChannels.map(c=>`<a class="social-channel" href="${c.url}" ${externalAttrs()}><span class="social-channel-logo">${icon(c.icon)}</span><span class="eyebrow">VILLE DE MEUDON</span><h2>${c.name}</h2><p>${c.desc}</p><span class="social-channel-handle">${c.handle}</span><span class="social-channel-cta">Ouvrir le compte officiel ${icon('arrow-up-right')}</span><span class="sr-only">Nouvel onglet</span></a>`).join('')}</div><div class="social-source-note"><p>Comptes reliés depuis le site officiel de la Ville. Aucun fil social n’est chargé automatiquement : vous choisissez la plateforme à ouvrir.</p><a href="${official.home}" ${externalAttrs()} class="text-link">Source : meudon.fr ${icon('external')}</a></div><div class="subtle-box">${icon('camera')}<p><strong>Les photos de Meudon, aussi sur le site.</strong><br>La galerie permet de découvrir les images sans compte sur un réseau social.</p><a href="#/galerie" class="button primary small">Ouvrir les albums ${icon('arrow-right')}</a></div></section>`}
function sitemapView(){return `${pageTop('Plan du site','Un repère pour chaque besoin.','Les pages du prototype et les services officiels, accessibles directement.')}<section class="wrap page-content"><div class="sitemap-grid">${Object.values(menuGroups).map(m=>`<section><h2>${m.title}</h2>${m.items.map(menuLink).join('')}</section>`).join('')}</div><div class="subtle-box">${icon('grid')}<p><strong>Tous les portails, au même endroit.</strong><br>L’annuaire vous permet de chercher un service par mot-clé, catégorie ou nom de site.</p><a href="#/services" class="button primary">Ouvrir l’annuaire ${icon('arrow-right')}</a></div></section>`}

const associationState={query:''};
const agendaExtra={district:'Tous',organizer:'Tous',audience:'Tous'};
function catalogItems(){return [...municipalNetwork.filter(s=>!['services','formulaires','associations'].includes(s.id)).map(s=>({...s,aliases:s.id==='demarches'?['services.meudon.fr','demarches.services.meudon.fr']:[],keywords:s.keywords+(s.id==='demarches'?' services formulaires suivi demande':''),category:s.category==='Vie quotidienne'?'Cadre de vie':s.category,kind:'portal',key:'portal-'+s.id,to:'#/service/'+s.id})),...civicServices.map(s=>({...s,kind:'portal',key:'civic-'+s.id,to:'#/service/'+s.id}))]}
function portalById(id){return catalogItems().find(s=>s.id===id)||municipalNetwork.find(s=>s.id===id)}
function pageItem(id,title,desc,category,iconName,to,keywords){return{id,title,desc,category,icon:iconName,to,keywords,kind:'journey',key:'page-'+id}}
function unifiedSearchItems(){return [...catalogItems(),pageItem('quartier','Mon quartier : lieux, travaux et conseils','Choisir un quartier et retrouver ses informations de proximité.','Cadre de vie','map','#/quartiers','carte plan quartier quartiers bellevue fleury centre seine foret travaux'),pageItem('activites','Activités et inscriptions','Trouver une activité régulière, sportive ou culturelle.','Culture & sport','sports','#/activites','activite cours sport culture loisirs adulte enfant'),pageItem('agenda','Agenda des sorties','Les événements de la Ville et des associations.','Culture & sport','calendar','#/agenda','agenda evenement sortir week end weekend spectacle concert'),pageItem('associations','Trouver une association','Chercher une association par nom, activité ou domaine.','Associations','users','#/associations','association benevolat club solidarite'),pageItem('contact','Horaires et contact de la mairie','Téléphone, adresses et horaires des accueils.','La mairie','phone','#/contact','mairie contact horaire telephone adresse ouvert'),...associationRecords.map(a=>({...a,id:'association-'+a.id,title:a.name,desc:a.description,category:'Associations',icon:'users',keywords:a.category+' '+a.activity+' '+a.audience,kind:'journey',key:'assoc-'+a.id,to:'#/association/'+a.id})),...socialChannels.map(s=>({...s,title:s.name+' — Ville de Meudon',keywords:s.name+' reseaux sociaux '+s.handle,category:'Réseaux sociaux',kind:'social',key:'social-'+s.id}))]}
function resultLink(s,cls='search-result'){const ext=s.kind==='social';return `<a class="${cls}" href="${s.to||s.url}" ${ext?externalAttrs():'data-action="close-link"'}>${icon(s.icon||'file')}<div><span class="result-type">${esc(s.category)}</span><h3>${esc(s.title)}</h3><p>${esc(s.desc||'')}</p></div>${icon(ext?'external':'arrow-right')}</a>`}
function unifiedResults(q){const box=$('#search-results');if(!q.trim()){box.innerHTML='<p>Essayez une démarche, une activité ou un équipement.</p>';return}const list=MeudonSearch.rank(q,unifiedSearchItems()).slice(0,8);box.innerHTML=list.length?`<p class="search-results-heading" role="status">${list.length} résultat${list.length>1?'s':''} pour « ${esc(q)} »</p>${list.map(s=>resultLink(s)).join('')}`:`<div class="empty-state"><h3>Nous n’avons pas trouvé de réponse précise.</h3><p>Essayez un autre mot ou contactez la mairie pour être orienté.</p><div class="modal-actions"><a class="button primary" href="#/contact" data-action="close-link">Contacter la mairie</a><a class="button outline" href="#/services" data-action="close-link">Tous les services</a></div></div>`;hydrate(box)}
function networkLink(s,compact=false){return `<article class="portal-row ${compact?'compact':''}"><span class="portal-symbol">${icon(s.icon||'file')}</span><div class="portal-main"><span class="eyebrow">${esc(s.category)}</span><a class="portal-title" href="#/service/${s.id}">${esc(s.title)} ${icon('arrow-right')}</a><p>${esc(s.desc)}</p></div>${compact?'':`<button class="portal-favorite icon-button" data-action="save-service" data-id="${s.id}" aria-pressed="${serviceFavorites.includes(s.id)}" aria-label="${serviceFavorites.includes(s.id)?'Retirer':'Ajouter'} ${esc(s.title)} ${serviceFavorites.includes(s.id)?'de mes':'à mes'} raccourcis">${icon('bookmark')}</button>`}</article>`}
function directoryView(){return `${pageTop('Démarches & services','Votre besoin. Le bon service.','Recherchez une démarche, un équipement ou une aide. Chaque fiche vous indique où agir et comment être accompagné.')}<section class="wrap page-content"><div class="directory-searchbar"><label class="page-search">${icon('search')}<input id="directory-search" type="search" placeholder="Ex. : cantine, logement social, passeport…" aria-label="Rechercher un service" value="${esc(directoryState.query)}"></label><button class="chip directory-saved" data-action="directory-saved" aria-pressed="${directoryState.savedOnly}">${icon('bookmark')} Mes raccourcis <span id="favorite-services-count">${serviceFavorites.length}</span></button></div><div class="directory-layout"><aside class="directory-sidebar"><span class="eyebrow">Par thème</span><div id="directory-filters">${directoryCategories.map(c=>`<button class="directory-category ${c===directoryState.category?'active':''}" data-action="directory-filter" data-value="${c}" aria-pressed="${c===directoryState.category}">${c}</button>`).join('')}</div><div class="directory-human">${icon('phone')}<strong>Besoin d’être accompagné ?</strong><a href="#/contact">Contacter la mairie ${icon('arrow-right')}</a></div></aside><div><div class="directory-results-top"><p id="directory-count" role="status"></p><label>Trier <select id="directory-sort"><option value="usage">Par besoin</option><option value="az" ${directoryState.sort==='az'?'selected':''}>De A à Z</option></select></label></div><div id="directory-results"></div><p class="directory-footnote">Les démarches se poursuivent sur les services officiels. Vos raccourcis restent sur cet appareil.</p></div></div></section>`}
function updateDirectory(){let list=directoryState.query.trim()?MeudonSearch.rank(directoryState.query,catalogItems()):catalogItems();list=list.filter(s=>(directoryState.category==='Tous'||s.category===directoryState.category)&&(!directoryState.savedOnly||serviceFavorites.includes(s.id)));if(directoryState.sort==='az')list.sort((a,b)=>a.title.localeCompare(b.title,'fr'));$('#directory-count').textContent=`${list.length} service${list.length>1?'s':''}${directoryState.query?' pour « '+directoryState.query+' »':''}`;$('#directory-results').innerHTML=list.length?list.map(s=>networkLink(s)).join(''):`<div class="empty-state"><h3>${directoryState.savedOnly?'Aucun raccourci dans cette sélection.':'Aucun service avec ces critères.'}</h3><p>Retirez les filtres ou contactez la mairie pour être orienté.</p><button class="button outline" data-action="reset-directory">Réinitialiser les filtres</button><a class="text-link" href="#/contact">Contacter la mairie ${icon('arrow-right')}</a></div>`;hydrate($('#directory-results'))}
function servicePage(id){const s=portalById(id);if(!s)return notFound();return `${pageTop('Démarches & services',esc(s.title),esc(s.desc))}<section class="wrap page-content"><div class="service-layout"><article class="service-guide"><div class="service-summary"><span class="eyebrow">Votre point de départ</span><h2>${esc(s.guideTitle||'Accéder aux informations et au service')}</h2><p>${esc(s.note||s.summary||'La page officielle précise les modalités et les contacts du service.')}</p><a class="button primary" href="${s.url}" ${externalAttrs()}>${esc(s.action||'Ouvrir le service officiel')} ${icon('external')}<span class="sr-only"> — nouvel onglet</span></a><p class="destination-note">${esc(s.brand||'Ville de Meudon')} · ${esc(new URL(s.url).hostname)} · nouvel onglet</p></div><h2>Préparer votre démarche</h2><ol class="step-list">${(s.steps||['Consultez les conditions et les modalités sur la page officielle.','Vérifiez les justificatifs, les échéances et le besoin éventuel d’un rendez-vous.','Effectuez votre demande auprès du service indiqué.']).map((step,i)=>`<li><span>${i+1}</span><p>${esc(step)}</p></li>`).join('')}</ol><p class="source-caption">Lien et informations vérifiés le 11 octobre 2026. Les disponibilités et conditions à jour sont celles du service officiel.</p></article><aside class="service-aside"><h2>En pratique</h2><dl><dt>Pour qui ?</dt><dd>${esc(s.audience||'Habitants de Meudon')}</dd><dt>Service</dt><dd>${esc(s.brand||'Ville de Meudon')}</dd></dl><button class="button outline" data-action="save-service" data-id="${s.id}" aria-pressed="${serviceFavorites.includes(s.id)}">${icon('bookmark')} ${serviceFavorites.includes(s.id)?'Retirer de mes raccourcis':'Enregistrer ce service'}</button><div class="aside-help"><h3>Un contact humain</h3><p>La mairie vous aide à trouver le bon interlocuteur.</p><a href="#/contact" class="text-link">Horaires et contacts ${icon('arrow-right')}</a></div></aside></div><a href="#/services" class="text-link return-link">${icon('arrow-left')} Tous les services</a></section>`}
function associationView(){return `${pageTop('Associations','Les associations de Meudon','Trouvez une activité, une cause à soutenir ou un collectif à rejoindre.',`<a class="button outline" href="#/espace-associations">Je représente une association ${icon('arrow-right')}</a>`)}<section class="wrap page-content"><div class="association-tools"><label class="page-search">${icon('search')}<input id="association-search" type="search" value="${esc(associationState.query)}" placeholder="Nom, activité, public…" aria-label="Rechercher une association"></label><div class="filter-row" id="assoc-filters">${chips(['Tout','Sport','Culture','Solidarité','Nature'],'assoc-filter',state.assocFilter)}</div></div><p id="association-count" role="status"></p><div class="association-list" id="assoc-list"></div><div class="association-source"><p>Sélection d’associations réelles issues de l’annuaire municipal. Horaires et inscriptions à confirmer auprès de chaque association.</p><a href="${official.association}" ${externalAttrs()} class="text-link">L’annuaire municipal complet ${icon("external")}</a></div><div class="subtle-box">${icon('calendar')}<p><strong>Les événements associatifs sont aussi dans l’agenda.</strong><br>Un filtre permet de retrouver les rendez-vous proposés par les associations.</p><a class="button primary" href="#/agenda?organisateur=association">Voir leurs événements ${icon('arrow-right')}</a></div></section>`}
function filterAssociations(){const q=MeudonSearch.clean(associationState.query);const list=associationRecords.filter(a=>(state.assocFilter==='Tout'||a.category===state.assocFilter)&&(!q||q.split(' ').every(t=>MeudonSearch.clean(a.name+' '+a.description+' '+a.activity+' '+a.audience).includes(t))));$('#association-count').textContent=`${list.length} association${list.length>1?'s':''} dans cette sélection`;$('#assoc-list').innerHTML=list.length?list.map(a=>`<article class="association-card"><div class="association-avatar">${icon(({Sport:'sports',Culture:'book',Solidarité:'heart',Nature:'leaf'})[a.category])}</div><div><span class="eyebrow">${a.category}</span><h3><a href="#/association/${a.id}">${esc(a.name)}</a></h3><p>${esc(a.description)}</p><p class="association-audience">${esc(a.audience||'Public : contacter l’association')}</p><a class="text-link" href="#/association/${a.id}">Activités et contact ${icon('arrow-right')}</a></div></article>`).join(''):`<div class="empty-state"><h3>Aucune association dans cette sélection.</h3><p>Essayez un autre mot ou consultez l’annuaire complet.</p><button class="button outline" data-action="reset-associations">Effacer les filtres</button><a class="text-link" href="${official.association}" ${externalAttrs()}>Annuaire municipal ${icon('external')}</a></div>`;hydrate($('#assoc-list'))}
function associationPage(id){const a=associationRecords.find(a=>a.id===id);if(!a)return notFound();return `${pageTop('Associations',esc(a.name),esc(a.description))}<section class="wrap page-content"><div class="service-layout"><article class="service-guide"><span class="eyebrow">${a.category}</span><h2>Activités proposées</h2><p>${esc(a.activity)}</p><dl class="portal-facts"><div><dt>Public</dt><dd>${esc(a.audience||'À confirmer auprès de l’association')}</dd></div>${a.place?`<div><dt>Lieu indiqué</dt><dd>${esc(a.place)}</dd></div>`:''}</dl><h2>Rejoindre l’association</h2><p>Contactez l’association pour connaître les créneaux, les conditions d’adhésion et les places disponibles.</p><a class="button primary" href="${a.url}" ${externalAttrs()}>Consulter sa page de référence ${icon('external')}</a><p class="source-caption">Données de l’annuaire municipal consultées le 11 octobre 2026. Aucune disponibilité n’est garantie par cette maquette.</p></article><aside class="service-aside"><h2>Contact</h2>${a.email?`<a class="contact-line" href="mailto:${esc(a.email)}">${icon('mail')}${esc(a.email)}</a>`:''}${a.phone?`<a class="contact-line" href="tel:${a.phone.replace(/[^+\d]/g,'')}">${icon('phone')}${esc(a.phone)}</a>`:''}<a class="text-link" href="${a.source}" ${externalAttrs()}>Source municipale ${icon('external')}</a><div class="aside-help"><h3>Vous représentez une association ?</h3><a class="text-link" href="#/espace-associations">Accéder à votre espace ${icon('arrow-right')}</a></div></aside></div><a class="text-link return-link" href="#/associations">${icon('arrow-left')} Toutes les associations</a></section>`}
function associationOfficeView(){return `${pageTop('Espace associations','Faire connaître votre association','Vos contacts et vos accès pour participer à la vie locale.')}<section class="wrap page-content"><div class="office-grid"><article class="office-feature"><span class="eyebrow">Événements</span><h2>Proposer un événement à l’agenda</h2><p>Préparez une fiche avec le titre, la date, le lieu et les informations utiles aux habitants.</p><button class="button primary" data-action="submit-event">Créer un aperçu ${icon('plus')}</button><p class="form-note">Parcours de démonstration : aucune proposition n’est envoyée.</p></article><div class="office-links">${associationOfficeLinks.map(s=>`<a href="${s.url}" ${externalAttrs()}><h3>${esc(s.title)} ${icon('external')}</h3><p>${esc(s.desc)}</p></a>`).join('')}</div></div><a class="text-link return-link" href="#/associations">${icon('arrow-left')} Trouver une association</a></section>`}
function familyView(){const age=state.age||'Tous les âges';const ids=age==='Moins de 3 ans'?['creche-information','creche']:age==='11 ans et plus'?['famille','conservatoire','mediatheques','piscine']:['inscription-scolaire','periscolaire','famille','sports','conservatoire'];const list=[...new Set(age==='Tous les âges'?['creche-information','creche',...ids]:ids)].map(portalById).filter(Boolean);return `${pageTop('Enfance & famille','Les services pour votre enfant','Choisissez un âge pour repérer les démarches utiles, puis consultez les conditions propres à chaque service.')}<section class="wrap page-content"><div class="family-panel"><span class="eyebrow">L’âge de mon enfant</span><div class="filter-row">${chips(['Tous les âges','Moins de 3 ans','3 à 5 ans','6 à 10 ans','11 ans et plus'],'family-age',age)}</div><p>L’âge affine les accès proposés. Le service officiel confirme les conditions d’accueil et d’inscription.</p></div><div class="family-results" role="region" aria-label="Services adaptés à la tranche d’âge"><div class="portal-home-grid">${list.map(s=>networkLink(s,true)).join('')}</div></div><div class="subtle-box">${icon('sports')}<p><strong>Vous cherchez un cours ou une activité ?</strong><br>Découvrez les pratiques sportives, culturelles et associatives.</p><a class="button outline" href="#/activites">Trouver une activité ${icon('arrow-right')}</a></div><div class="subtle-box">${icon('phone')}<p><strong>Besoin d’aide pour une inscription ?</strong><br>Les accueils municipaux peuvent vous orienter.</p><a class="text-link" href="#/contact">Contacter la mairie ${icon('arrow-right')}</a></div></section>`}
function activitiesView(){const groups=[{name:'Sport',desc:'Pratiquer régulièrement, apprendre ou rejoindre un club.',ids:['sports','piscine'],cat:'Sport',icon:'sports'},{name:'Culture',desc:'Musique, découverte, lecture et pratiques artistiques.',ids:['conservatoire','mediatheques','ludotheque'],cat:'Culture',icon:'book'}];return `${pageTop('Activités','Trouver une activité régulière','Cours, pratiques sportives, culture et loisirs : choisissez votre point de départ.')}<section class="wrap page-content"><div class="activity-columns">${groups.map(g=>`<section class="activity-column"><span class="activity-icon">${icon(g.icon)}</span><h2>${g.name}</h2><p>${g.desc}</p>${g.ids.map(portalById).filter(Boolean).map(s=>`<a class="activity-link" href="#/service/${s.id}">${esc(s.title)} ${icon('arrow-right')}</a>`).join('')}<a class="text-link" href="#/associations?categorie=${g.cat}">Les associations de ${g.name.toLowerCase()} ${icon('arrow-right')}</a></section>`).join('')}</div><div class="subtle-box">${icon('calendar')}<p><strong>Vous cherchez une sortie ponctuelle ?</strong><br>Concerts, expositions et rendez-vous se trouvent dans l’agenda.</p><a class="button primary" href="#/agenda">Consulter l’agenda ${icon('arrow-right')}</a></div></section>`}
function townView(){return `${pageTop('La mairie','Votre mairie, vos interlocuteurs','Contacts, décisions municipales, projets et informations publiques.')}<section class="wrap page-content"><div class="town-grid">${[pageItem('contact','Horaires et contacts','Les accueils et les coordonnées de la mairie.','La mairie','phone','#/contact',''),pageItem('projets','Projets et participation','Comprendre les projets et donner son avis.','La mairie','compass','#/participer',''),...catalogItems().filter(s=>s.category==='La mairie')].map(s=>resultLink(s,'town-link')).join('')}</div><div class="subtle-box">${icon('grid')}<p><strong>Les données publiques</strong><br>Accédez aux jeux de données de Meudon et de Grand Paris Seine Ouest.</p><a class="button outline" href="#/services?categorie=Données%20publiques">Consulter les données ${icon('arrow-right')}</a></div></section>`}
function districtView(){return `${pageTop('Mon quartier','Les informations près de chez vous','Sélectionnez votre quartier pour retrouver ses lieux, les conseils de quartier et les dossiers qui le concernent.')}<section class="wrap page-content"><div class="filter-row" id="district-tabs">${districts.map((d,i)=>`<a class="chip ${state.district===i?'active':''}" href="#/quartiers?quartier=${i}" ${state.district===i?'aria-current="true"':''}>${d.name}</a>`).join('')}</div><div id="district-content"></div></section>`}
function districtContent(){const d=districts[state.district],local=districtRecords[state.district];return `<div class="district-lead"><div><span class="eyebrow">Votre quartier</span><h2>${d.name}</h2><p>${d.desc}</p><p class="source-caption">Les liens ci-dessous conduisent aux informations municipales. Aucun état de circulation en temps réel n’est affiché.</p></div>${img(d.image)}</div><div class="district-service-grid">${local.links.map(s=>`<article><span class="eyebrow">${esc(s.category)}</span><h3>${esc(s.title)}</h3><p>${esc(s.desc)}</p><a class="text-link" href="${s.url}" ${externalAttrs()}>${esc(s.action||'Consulter les informations')} ${icon('external')}</a></article>`).join('')}</div><section class="council-section"><div><span class="eyebrow">Conseil de quartier</span><h2>Les sujets, les échanges et les suites</h2><p>Retrouvez les documents publiés et les interlocuteurs de votre quartier.</p></div><div>${local.documents.map(s=>`<a class="document-row" href="${s.url}" ${externalAttrs()}>${icon('file')}<span><strong>${esc(s.title)}</strong><small>${esc(s.note||'Document ou page officielle de la Ville')}</small></span>${icon('external')}</a>`).join('')}</div></section><div class="subtle-box">${icon('calendar')}<p><strong>Les sorties de votre quartier</strong><br>Retrouvez les exemples d’événements localisés dans l’agenda de démonstration.</p><a class="button outline" href="#/agenda?quartier=${encodeURIComponent(d.name)}">Voir l’agenda du quartier ${icon('arrow-right')}</a></div>`}
function councilDialog(){location.hash='/quartiers?quartier='+state.district;closeDialog()}
function albumView(id){const album=photoAlbums.find(a=>a.id===id);if(!album)return notFound();return `${pageTop('Albums photo',album.title,album.desc)}<section class="wrap page-content"><div class="album-meta"><span>${album.images.length} photographies</span><span>Collection patrimoniale · dates des prises de vue dans les sources</span></div><div class="gallery-page">${album.images.map(galleryTile).join('')}</div><a class="text-link return-link" href="#/galerie">${icon('arrow-left')} Tous les albums</a></section>`}
function galleryView(){return `${pageTop('Albums photo','Meudon en images','Parcourez les collections photographiques de la ville.')}<section class="wrap page-content"><div class="album-grid">${photoAlbums.map(a=>`<a class="album-card" href="#/album/${a.id}">${img(a.images[0])}<div><span class="eyebrow">Collection patrimoniale · ${a.images.length} photos</span><h2>${a.title}</h2><p>${a.desc}</p><span class="text-link">Ouvrir l’album ${icon('arrow-right')}</span></div></a>`).join('')}</div><div class="subtle-box">${icon('camera')}<p><strong>Les reportages des événements municipaux</strong><br>Ces albums patrimoniaux présentent le parcours de consultation. Les reportages de la Ville pourront utiliser le même format, avec nom d’événement et date.</p><button class="text-link" data-action="credits">Crédits photographiques ${icon('arrow-right')}</button></div></section>`}
function agendaView(){return `${pageTop('Agenda','Les sorties à Meudon','Les rendez-vous municipaux et associatifs réunis dans un même agenda.')}<section class="wrap page-content agenda-page"><div class="demo-notice">Programmation de démonstration : événements, modalités et dates fictifs.</div><div class="agenda-toolbar"><div class="calendar-controls"><button class="icon-button" data-action="month" data-delta="-1" aria-label="Mois précédent">${icon('arrow-left')}</button><strong id="agenda-month"></strong><button class="icon-button" data-action="month" data-delta="1" aria-label="Mois suivant">${icon('arrow-right')}</button></div><button class="chip saved-toggle" data-action="saved-filter" aria-pressed="${state.savedOnly}">Mes favoris <span id="saved-count">(${saved.length})</span></button></div><div class="agenda-selects"><label>Quartier<select id="agenda-district"><option value="Tous">Tous les quartiers</option>${districts.map(d=>`<option ${agendaExtra.district===d.name?'selected':''}>${d.name}</option>`).join('')}</select></label><label>Organisateur<select id="agenda-organizer"><option value="Tous">Tous les organisateurs</option><option value="ville" ${agendaExtra.organizer==='ville'?'selected':''}>Ville et équipements</option><option value="association" ${agendaExtra.organizer==='association'?'selected':''}>Associations</option></select></label><label>Public<select id="agenda-audience"><option value="Tous">Tous les publics</option><option value="famille" ${agendaExtra.audience==='famille'?'selected':''}>En famille</option><option value="adulte" ${agendaExtra.audience==='adulte'?'selected':''}>Adultes</option></select></label></div><div class="filter-row" id="agenda-filters">${chips(['Tout','Culture','Nature','En famille','Sport'],'agenda-filter',state.agendaFilter)}</div><p id="agenda-count" role="status"></p><div class="event-grid" id="agenda-events"></div></section>`}
function filterAgenda(){const monthName=new Date(2026,state.agendaMonth-1,1).toLocaleDateString('fr-FR',{month:'long',year:'numeric'});$('#agenda-month').textContent=monthName;const list=events.filter(e=>e.month===state.agendaMonth&&(state.agendaFilter==='Tout'||e.category===state.agendaFilter)&&(!state.savedOnly||saved.includes(e.id))&&(agendaExtra.district==='Tous'||e.district===agendaExtra.district)&&(agendaExtra.organizer==='Tous'||e.orgType===agendaExtra.organizer)&&(agendaExtra.audience==='Tous'||e.audience===agendaExtra.audience));$('#agenda-count').textContent=`${list.length} événement${list.length>1?'s':''} dans cette sélection`;$('#agenda-events').innerHTML=list.length?list.map(eventCard).join(''):`<div class="empty-state"><h3>Aucun exemple avec ces critères.</h3><p>La sélection de démonstration couvre octobre et novembre 2026.</p><button class="button outline" data-action="reset-agenda">Afficher tous les exemples d’octobre</button></div>`;hydrate($('#agenda-events'))}
function home(){return `${cityHero()}<section class="quick-section"><div class="wrap"><div class="quick-heading"><h2>Je veux…</h2><a href="#/services" class="text-link">Toutes les démarches et services ${icon('arrow-right')}</a></div><div class="quick-grid">${[['Carte d’identité, passeport','file','#/service/identite'],['Inscrire mon enfant','child','#/famille'],['Trouver une activité','sports','#/activites'],['Trouver une association','users','#/associations'],['Signaler un problème','alert','#/service/signaler'],['M’informer sur mon quartier','pin','#/quartiers']].map(([t,ic,to])=>`<a class="quick-item" href="${to}">${icon(ic)}<span>${t}</span>${icon('arrow-right')}</a>`).join('')}</div></div></section><section class="wrap practical-band" data-reveal><div><span class="eyebrow">Infos pratiques</span><h2>Les accès utiles</h2></div><div>${[['Inscriptions et cantine','famille'],['Déchets et collecte','dechets'],['Stationnement','stationnement'],['Actualités municipales','actualites']].map(([t,id])=>`<a href="#/service/${id}">${t}${icon('arrow-up-right')}</a>`).join('')}</div></section><section class="agenda-section section"><div class="wrap"><div class="section-header"><div><span class="eyebrow">Ville & associations</span><h2>Les prochains rendez-vous</h2></div><a href="#/agenda" class="text-link">Tous les événements ${icon('arrow-right')}</a></div><p class="demo-caption">Programmation illustrative · événements et dates fictifs</p><div class="event-grid">${events.slice(0,3).map(eventCard).join('')}</div></div></section><section class="wrap section neighborhood-section"><div><span class="eyebrow">Proximité</span><h2>Dans votre quartier</h2><p>Les lieux utiles, les dossiers de travaux et les comptes rendus des conseils de quartier, accessibles depuis un même endroit.</p><div class="home-district-links">${districts.map((d,i)=>`<a href="#/quartiers?quartier=${i}">${d.name}${icon('arrow-right')}</a>`).join('')}</div></div><a href="#/quartiers" class="neighborhood-preview" aria-label="Choisir mon quartier"><div class="perspective-photo main-photo">${img(5)}<span>Meudon depuis l’Observatoire</span></div><div class="perspective-photo detail-photo">${img(4)}<span>Le viaduc du Val-Fleury</span></div></a></section><section class="association-home" data-reveal><div class="wrap"><div class="section-header"><div><span class="eyebrow">Vie associative</span><h2>Les associations de Meudon</h2><p>Sport, culture, solidarité et nature : découvrez les associations de Meudon.</p></div><a href="#/associations" class="button primary">Trouver une association ${icon('arrow-right')}</a></div><div class="association-home-list">${associationRecords.filter(a=>['asm-tennis','plakka','jardin-amelie'].includes(a.id)).map(a=>`<a href="#/association/${a.id}"><span>${a.category}</span><strong>${esc(a.name)}</strong>${icon('arrow-up-right')}</a>`).join('')}</div><a class="text-link" href="#/espace-associations">Vous représentez une association ? Accédez à votre espace ${icon('arrow-right')}</a></div></section><section class="wrap section"><div class="section-header"><div><span class="eyebrow">Culture & patrimoine</span><h2>Culture et patrimoine</h2></div><a href="#/decouvrir" class="text-link">Les lieux à découvrir ${icon('arrow-right')}</a></div><div class="news-layout"><a href="#/service/hangar" class="feature-story tilt">${img(1)}<div class="story-text"><span class="tag">Art & patrimoine</span><h3>Le Hangar Y</h3><p>Un lieu emblématique à explorer.</p></div></a><div class="news-side"><a href="#/album/paysages" class="mini-story"><div><span class="tag">Nature</span><h3>Les paysages de Meudon</h3><span class="text-link">Voir les photos ${icon('arrow-right')}</span></div>${img(2)}</a><a href="#/service/musee" class="mini-story"><div><span class="tag">Culture</span><h3>Le musée d’art et d’histoire</h3><span class="text-link">Préparer sa visite ${icon('arrow-right')}</span></div>${img(3)}</a></div></div></section>${cityStats()}<section class="wrap section"><div class="section-header"><div><span class="eyebrow">Photothèque</span><h2>Les albums de Meudon</h2></div><a href="#/galerie" class="text-link">Tous les albums ${icon('arrow-right')}</a></div><div class="album-home-grid">${photoAlbums.map(a=>`<a href="#/album/${a.id}">${img(a.images[0])}<div><h3>${a.title}</h3><span>${a.images.length} photos ${icon('arrow-right')}</span></div></a>`).join('')}</div></section><section class="wrap home-social"><div><span class="eyebrow">Suivre la Ville</span><h2>Meudon sur les réseaux</h2></div><div>${socialLinks()}</div></section>`}

function syncHeroPhoto(n){const labels=['La terrasse de l’Observatoire','Le Hangar Y','L’étang de Villebon'];const label=$('#hero-place-label');if(!label)return;label.textContent=labels[n];$('#hero-place-link').href=['#/decouvrir','#/service/hangar','#/album/paysages'][n];$('#hero-photo-number').textContent=String(n+1).padStart(2,'0');$$('[data-action=hero-photo]').forEach(el=>el.setAttribute('aria-pressed',String(Number(el.dataset.id)===n)))}
function cityHero(){return `<section class="city-hero"><div class="city-hero-copy"><span class="eyebrow city-kicker"><span></span> Hauts-de-Seine · Île-de-France</span><h1><span class="headline-line"><span>Bienvenue</span></span> <span class="headline-line"><span>à Meudon<span class="title-point">.</span></span></span></h1><p class="city-hero-description">Recherchez un service, consultez l’agenda ou retrouvez les informations de votre quartier.</p><form class="hero-search city-search" data-form="hero-search">${icon('search')}<label class="sr-only" for="hero-query">Rechercher dans Meudon</label><input id="hero-query" name="query" placeholder="Que recherchez-vous ?" autocomplete="off"><button type="button" class="icon-button" data-action="voice-intro" aria-label="Rechercher avec la voix">${icon('mic')}</button><button type="submit" class="icon-button search-submit" aria-label="Rechercher">${icon('arrow-right')}</button></form><div class="city-hero-shortcuts"><span>Accès directs</span><button data-action="search-example" data-value="Payer la cantine">Cantine</button><button data-action="search-example" data-value="Passeport">Passeport</button><a href="#/contact">Horaires</a></div><a class="city-discover-link" href="#/decouvrir">Découvrir Meudon ${icon('arrow-up-right')}</a></div><div class="city-hero-photo"><div class="hero-photo-stage" id="hero-photo-stage" data-photo="0">${img(0,'',true)}</div><span class="hero-photo-tag">Le patrimoine de Meudon</span><button class="hero-enlarge" data-action="hero-enlarge" aria-label="Voir la photographie en grand">${icon("camera")}<span>Voir en grand</span></button><div class="hero-photo-bottom"><a href="#/decouvrir" id="hero-place-link"><span class="hero-photo-count" aria-hidden="true"><strong id="hero-photo-number">01</strong><span>/ 03</span></span><span id="hero-place-label">La terrasse de l’Observatoire</span>${icon('arrow-up-right')}</a><div class="hero-photo-controls" aria-label="Choisir une photographie">${[{id:0,label:'L’Observatoire'},{id:1,label:'Le Hangar Y'},{id:2,label:'La nature'}].map((p,i)=>`<button type="button" data-action="hero-photo" data-id="${p.id}" aria-label="Voir ${p.label}" aria-pressed="${i===0}"><img src="${A+photos[p.id].file}" alt="" width="64" height="48" loading="lazy"><span aria-hidden="true">0${i+1}</span></button>`).join('')}</div></div></div></section>`}
function discoverView(){return `<section class="city-intro wrap"><div class="breadcrumb"><a href="#/">Accueil</a><span>/</span><span>Découvrir Meudon</span></div><div class="city-intro-title"><div><span class="eyebrow">La ville</span><h1>Découvrir<br>Meudon</h1></div><div><p>L’Observatoire, la forêt, le Hangar Y et les cinq quartiers : retrouvez les principaux lieux et repères de Meudon.</p><button class="text-link" data-action="chapter" data-target="ville-reperes">La ville en quelques repères ${icon('arrow-right')}</button></div></div><figure class="city-panorama" data-reveal>${img(5,'',true)}<figcaption><span>Depuis la terrasse de l’Observatoire</span><span>Meudon · Hauts-de-Seine</span></figcaption></figure></section><div class="city-chapter-nav" aria-label="Sommaire de la présentation"><div class="wrap"><span>Découvrir Meudon</span>${[['Repères','ville-reperes'],['Nature','ville-nature'],['Patrimoine','ville-patrimoine'],['Culture','ville-culture'],['Quartiers','ville-quartiers']].map(([label,id])=>`<button data-action="chapter" data-target="${id}">${label}</button>`).join('')}</div></div><div id="ville-reperes" class="chapter-target">${cityStats()}</div><section class="wrap city-story chapter-target" id="ville-nature"><figure class="city-story-photo" data-reveal>${img(2)}<figcaption>L’étang de Villebon</figcaption></figure><div class="city-story-copy" data-reveal><span class="eyebrow">01 / Nature</span><h2>La forêt<br>et les étangs</h2><p>Retrouvez les photographies de l’étang de Villebon, de la terrasse de l’Observatoire et des paysages de Meudon.</p><a href="#/album/paysages" class="button outline">Voir l’album des paysages ${icon('arrow-right')}</a><span class="story-footnote">Photographies de Meudon · collection patrimoniale</span></div></section><section class="city-story-dark chapter-target" id="ville-patrimoine"><div class="wrap city-story reversed"><div class="city-story-copy" data-reveal><span class="eyebrow">02 / Patrimoine</span><h2>Le patrimoine<br>de Meudon</h2><p>L’Observatoire, le viaduc du Val-Fleury, le Hangar Y : des architectures singulières, des repères familiers et des points de vue à redécouvrir.</p><a href="#/album/patrimoine" class="button outline">Voir l’album patrimoine ${icon('arrow-right')}</a></div><figure class="city-story-photo tall" data-reveal>${img(4)}<figcaption>Le viaduc du Val-Fleury</figcaption></figure></div></section><section class="wrap city-culture chapter-target" id="ville-culture"><div class="section-header" data-reveal><div><span class="eyebrow">03 / Culture</span><h2>Les lieux de culture</h2></div><p>Une exposition, un livre, un spectacle.<br>Les accès pour préparer votre prochaine visite.</p></div><a class="culture-feature" href="#/service/hangar" data-reveal><div>${img(1)}</div><article><span class="eyebrow">Art & patrimoine</span><h3>Le Hangar Y</h3><p>Découvrez le lieu et retrouvez les informations utiles à votre visite.</p><span class="text-link">Préparer ma visite ${icon('arrow-up-right')}</span></article></a><div class="culture-pair"><a href="#/service/musee" data-reveal>${img(3)}<div><span class="eyebrow">Collections & jardin</span><h3>Musée d’art et d’histoire</h3><span class="text-link">Découvrir le musée ${icon('arrow-up-right')}</span></div></a><a href="#/service/mediatheques" class="culture-library" data-reveal><span class="library-lines" aria-hidden="true"></span><div><span class="eyebrow">Lecture & découverte</span><h3>Les médiathèques</h3><p>Catalogue, compte lecteur et ressources numériques.</p><span class="text-link">Accéder aux médiathèques ${icon('arrow-up-right')}</span></div></a></div></section><section class="city-districts chapter-target" id="ville-quartiers"><div class="wrap"><div class="section-header" data-reveal><div><span class="eyebrow">04 / Proximité</span><h2>Les cinq quartiers</h2></div><p>Lieux utiles, projets et conseils de quartier :<br>retrouvez les informations près de chez vous.</p></div><div class="city-district-list">${districts.map((d,i)=>`<a href="#/quartiers?quartier=${i}" data-reveal><span class="district-number">0${i+1}</span><h3>${d.name}</h3>${icon('arrow-up-right')}</a>`).join('')}</div></div></section><section class="wrap city-visit" data-reveal><div><span class="eyebrow">Sortir à Meudon</span><h2>Agenda, activités<br>et associations</h2></div><div><a href="#/agenda" class="button primary">Consulter l’agenda ${icon('calendar')}</a><a href="#/activites" class="text-link">Trouver une activité ${icon('arrow-right')}</a><a href="#/associations" class="text-link">Trouver une association ${icon('arrow-right')}</a></div></section>`}

const views={'/':home,'/services':directoryView,'/agenda':agendaView,'/quartiers':districtView,'/associations':associationView,'/participer':participationView,'/galerie':galleryView,'/decouvrir':discoverView,'/contact':contactView,'/famille':familyView,'/annuaire':directoryView,'/reseaux':socialsView,'/plan':sitemapView,'/activites':activitiesView,'/espace-associations':associationOfficeView,'/mairie':townView};
function render(animate=true){const raw=location.hash.slice(1)||'/';const [path,query='']=raw.split('?');const route=path==='/annuaire'?'/services':path;const params=new URLSearchParams(query);currentRoute=route;closeDialog();closeMenu();if(route==='/services'&&params.has('categorie')){const c=params.get('categorie');directoryState.category=directoryCategories.includes(c)?c:'Tous';directoryState.query='';directoryState.savedOnly=false}if(route==='/quartiers'&&params.has('quartier'))state.district=Number.isInteger(Number(params.get('quartier')))&&Number(params.get('quartier'))>=0&&Number(params.get('quartier'))<5?Number(params.get('quartier')):0;if(route==='/associations'&&params.has('categorie')){const c=params.get('categorie');state.assocFilter=['Sport','Culture','Solidarité','Nature'].includes(c)?c:'Tout';associationState.query=''}if(route==='/agenda'){if(params.has('organisateur'))agendaExtra.organizer=['ville','association'].includes(params.get('organisateur'))?params.get('organisateur'):'Tous';if(params.has('quartier'))agendaExtra.district=districts.some(d=>d.name===params.get('quartier'))?params.get('quartier'):'Tous'}const update=()=>{let view=views[route];if(route.startsWith('/service/'))view=()=>servicePage(route.slice(9));if(route.startsWith('/association/'))view=()=>associationPage(route.slice(13));if(route.startsWith('/album/'))view=()=>albumView(route.slice(7));$('#main').innerHTML=(view||notFound)();hydrate();if(route==='/services')updateDirectory();if(route==='/agenda')filterAgenda();if(route==='/quartiers'){$('#district-content').innerHTML=districtContent();hydrate()}if(route==='/associations')filterAssociations();syncNavigation(route);animateCounters();document.title=($('#main h1')?.textContent||'Accueil')+' — Meudon';window.scrollTo({top:0,behavior:'instant'});if(animate)$('#main').focus({preventScroll:true});document.dispatchEvent(new CustomEvent('meudon:route'))};if(animate&&document.startViewTransition&&!preferences.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches)document.startViewTransition(update);else update()}

function notFound(){return pageTop('Page introuvable','Reprenons le bon chemin.','Cette page ne fait pas partie de la maquette.',`<a href="#/" class="button primary">Retour à l’accueil ${icon('arrow-right')}</a>`)}
function normalize(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function filterServices(){const q=normalize(state.serviceQuery);const list=services.filter(s=>(state.serviceFilter==='Tout'||s.category===state.serviceFilter)&&normalize(s.title+' '+s.desc+' '+s.keywords).includes(q));$('#services-list').innerHTML=list.length?list.map(s=>serviceLink(s)).join(''):`<div class="empty-state"><h3>Essayons avec d’autres mots.</h3><p>Aucun service ne correspond à ce filtre.</p><button class="button outline" data-action="reset-services">Afficher tous les services</button></div>`;$('#services-count').textContent=`${list.length} parcours à votre disposition`;hydrate($('#services-list'))}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4000)}
function openDialog(html,cls=''){const trigger=document.activeElement;const fromMobile=$('#mobile-nav').contains(trigger);closeMega();closeMenu();const d=$('#dialog');if(!d.open)lastFocus=fromMobile?$('[data-action=menu]'):trigger;d.className=cls;$('#dialog-body').innerHTML=html;hydrate(d);if(!d.open)d.showModal();document.body.classList.add('modal-open');d.scrollTop=0;setTimeout(()=>{const target=$('input:not([type=checkbox])',d)||$('#dialog-title',d);if(target){if(target.tagName!=='INPUT')target.setAttribute('tabindex','-1');target.focus({preventScroll:true})}},70)}
function closeDialog(){const d=$('#dialog');if(d.open){d.close();document.body.classList.remove('modal-open');if(lastFocus?.isConnected)lastFocus.focus({preventScroll:true})}}
function contentDialog(eye,title,body){openDialog(`<div class="dialog-content"><span class="eyebrow">${eye}</span><h2 id="dialog-title">${title}</h2>${body}</div>`)}
function closeMenu(){closeMega();$('#mobile-nav').hidden=true;const b=$('[data-action=menu]');b.setAttribute('aria-expanded','false');b.setAttribute('aria-label','Ouvrir le menu');b.innerHTML=icon('menu');document.body.classList.remove('menu-open');setMenuInert(false)}
function searchModal(q=''){contentDialog('VOTRE POINT DE DÉPART','Comment vous aider ?',`<form class="search-modal-input" data-form="search">${icon('search')}<label class="sr-only" for="search-query">Votre recherche</label><input id="search-query" name="query" value="${esc(q)}" placeholder="Posez votre question, simplement…" autocomplete="off"><button type="submit" aria-label="Lancer la recherche">${icon('arrow-right')}</button></form><div class="search-example-row">${['Payer la cantine','Réserver un livre','Un spectacle','Open data'].map(t=>`<button data-action="search-example" data-value="${t}">${t}</button>`).join('')}</div><div id="search-results" aria-live="polite"></div><p class="form-note">Recherche dans les pages et les services référencés par la maquette.</p><button class="text-link" data-action="voice-intro">${icon('mic')} Utiliser ma voix</button>`);if(q)runSearch(q);else $('#search-results').innerHTML=`<p style="padding-top:10px">Dites-nous ce que vous souhaitez faire. Nous vous orientons vers les bons services.</p>`}
function runSearch(q){unifiedResults(q)}
function serviceDetail(id){const routes={demarche:'/services',signaler:'/service/signaler',travaux:'/quartiers',equipement:'/services?categorie=Culture%20%26%20sport',service:'/services'};closeDialog();location.hash=routes[id]||'/services'}

function eventDialog(id){const e=events.find(e=>e.id===id);if(!e)return;openDialog(`${img(e.image,'modal-hero',true)}<div class="dialog-content"><span class="eyebrow">${e.category} · ÉVÉNEMENT FICTIF</span><h2 id="dialog-title">${e.title}</h2><div class="event-modal-meta"><span>${icon('calendar')}${e.day} ${e.month===10?'octobre':'novembre'} 2026</span><span>${icon('clock')}${e.time.replace(':','h')}</span><span>${icon('pin')}${e.place}</span></div><p>${e.desc}</p><dl class="portal-facts"><div><dt>Quartier</dt><dd>${e.district}</dd></div><div><dt>Public</dt><dd>${e.audience==='famille'?'En famille':'Adultes'} · exemple</dd></div><div><dt>Tarif</dt><dd>Gratuit · modalité fictive</dd></div><div><dt>Réservation</dt><dd>Aucune inscription possible dans la maquette</dd></div></dl><p><strong>${e.organizer}</strong></p><div class="modal-actions"><button class="button primary" data-action="save-event" data-id="${e.id}">${icon('bookmark')}<span>${saved.includes(e.id)?'Retirer de mes favoris':'Enregistrer ce rendez-vous'}</span></button><button class="button outline" data-action="ical" data-id="${e.id}">${icon('download')}Exporter l’exemple (.ics)</button></div><p class="result-note">Démonstration uniquement · Aucune réservation · Favoris conservés dans ce navigateur.</p></div>`)}
function gallerySequence(){return photoAlbums.find(a=>currentRoute==='/album/'+a.id)?.images||photos.map((_,i)=>i)}
function galleryStep(delta){const seq=gallerySequence();galleryDialog(seq[(seq.indexOf(state.galleryIndex)+delta+seq.length)%seq.length])}
function galleryDialog(i){const seq=gallerySequence();state.galleryIndex=seq.includes(i)?i:seq[0];const p=photos[state.galleryIndex];openDialog(`${img(state.galleryIndex,'',true)}<div class="lightbox-footer"><div><h2 id="dialog-title">${p.title}</h2><p>${p.label} · ${p.credit} · ${seq.indexOf(state.galleryIndex)+1} / ${seq.length}</p><button data-action="credits" style="color:#ccdbbe;font-size:10px;text-decoration:underline;padding:0">Source et licence</button></div><div class="lightbox-controls"><button class="icon-button" data-action="gallery-prev" aria-label="Photo précédente">${icon('arrow-left')}</button><button class="icon-button" data-action="gallery-next" aria-label="Photo suivante">${icon('arrow-right')}</button></div></div>`,'lightbox')}
function projectDialog(id){const geo=id==='geo';contentDialog('Projets de la Ville',geo?'Géothermie à Meudon-la-Forêt':'Meudon 2040',geo?`<p>Le projet vise à utiliser la chaleur du sous-sol pour le réseau de chaleur de Meudon-la-Forêt.</p><dl class="portal-facts"><div><dt>Calendrier annoncé</dt><dd>Mise en service annoncée pour octobre 2027 sur la page municipale actualisée le 29 septembre 2026.</dd></div><div><dt>Documents</dt><dd>Présentation du projet, étapes et informations sur le chantier.</dd></div></dl><a class="button primary" href="https://www.meudon.fr/projets-de-la-ville/geothermie/" ${externalAttrs()}>Lire le dossier officiel ${icon('external')}</a><a class="document-row" href="https://www.meudon.fr/app/uploads/1/2026/04/260407_PREZ_FORAGE.pdf" ${externalAttrs()}>${icon('file')}<span>Présentation de la réunion d’avril 2026 · PDF</span>${icon('external')}</a><p class="source-caption">Le calendrier peut évoluer. Consultez le dossier officiel pour les informations à jour ; aucun état de circulation en temps réel n’est affiché ici.</p>`:`<p>Le dossier Meudon 2040 présente les orientations de la Ville. Retrouvez les informations et les documents publiés par la municipalité.</p><div class="modal-actions"><a class="button primary" href="${official.projects}" ${externalAttrs()}>Consulter Meudon 2040 ${icon('external')}</a><a class="button outline" href="#/quartiers" data-action="close-link">Les projets de mon quartier ${icon('arrow-right')}</a></div>`)}
async function creditsDialog(){contentDialog('LE REGARD DES PHOTOGRAPHES','Des images,<br>et leurs auteurs.','<p>Chargement des crédits…</p>');try{const credits=await fetch('assets/credits.json').then(r=>r.json());contentDialog('LE REGARD DES PHOTOGRAPHES','Des images,<br>et leurs auteurs.',`<h3>Conception et réalisation du prototype</h3><p>Yanis Sadoun.</p><h3>Photographies</h3><p>Photographies authentiques de Meudon issues de Wikimedia Commons, redimensionnées et compressées en WebP. Les recadrages et filtres de présentation ne représentent pas de nouveaux événements.</p>${credits.map(c=>`<div style="padding:17px 0;border-bottom:1px solid var(--line)"><strong style="font-size:13px">${esc(c.alt)}</strong><p style="font-size:11px;margin:7px 0">${esc(c.author)} · ${esc(c.license)}<br>${esc(c.changes)}</p><a href="${c.sourcePage}" target="_blank" rel="noopener" style="font-size:11px">Photographie originale</a> · <a href="${c.licenseUrl}" target="_blank" rel="noopener" style="font-size:11px">Licence</a></div>`).join('')}<h3>Annuaire associatif et informations municipales</h3><p>30 associations et 135 activités référencées, dont 24 créneaux de l’École municipale des sports. Sélection non exhaustive. <a href="assets/discovery-sources-v6.json" target="_blank" rel="noopener">Sources du répertoire et des équipements</a>. <a href="assets/civic-sources.json" target="_blank" rel="noopener">Sources, date et licence de réutilisation</a>. <a href="assets/district-sources.json" target="_blank" rel="noopener">Sources des quartiers et comptes rendus</a>.</p><h3>Chiffres et annuaire de services</h3><p>Population municipale : <a href="https://www.insee.fr/fr/statistiques/8643952?geo=COM-92048" target="_blank" rel="noopener">INSEE, millésime 2023</a>, en vigueur au 1er janvier 2026. Quartiers et espaces verts : chiffres de la Ville publiés en mars 2025. <a href="assets/network-sources.json" target="_blank" rel="noopener">Sources détaillées de l’annuaire</a>.</p><h3>Identité municipale</h3><p><a href="https://www.meudon.fr/app/uploads/2025/10/logo_meudon_quadri-transparent.png" target="_blank" rel="noopener">Logo officiel de la Ville de Meudon</a>. Le blason et la signature conservent leurs couleurs et leurs proportions. Cette maquette n’est pas le site officiel.</p><h3>Sources éditoriales et inspirations</h3><p>Informations pratiques et liens : <a href="${official.home}" target="_blank" rel="noopener">Ville de Meudon</a>, consulté le 11 octobre 2026. Parcours inspirés de l’étude des sites de <a href="https://www.villederueil.fr/" target="_blank" rel="noopener">Rueil-Malmaison</a>, <a href="https://www.issy.com/" target="_blank" rel="noopener">Issy-les-Moulineaux</a>, <a href="https://www.vincennes.fr/" target="_blank" rel="noopener">Vincennes</a> et <a href="https://www.versailles.fr/" target="_blank" rel="noopener">Versailles</a> et du <a href="https://villeduraincy.fr/votre-ville/presentation-de-la-ville/" target="_blank" rel="noopener">Raincy</a>.</p><p>Typographie Manrope : Mikhail Sharanda et Mirko Velimirović, SIL Open Font License. Logo officiel : Ville de Meudon, fichier publié sur meudon.fr en octobre 2025, reproduit sans modification. Mise en page et animations : proposition de refonte, non validée par la Ville.</p>`)}catch{contentDialog('Crédits','Photographies de Meudon.',`<p>Les crédits détaillés sont disponibles dans le fichier de sources.</p><a href="assets/credits.json" class="text-link">Ouvrir les crédits complets</a>`)}}
function submitEventDialog(){contentDialog('ESPACE ASSOCIATIONS','Faites vivre<br>votre événement.',`<p>Testez la proposition d’un rendez-vous. Les informations restent dans cette fenêtre et ne sont ni envoyées ni enregistrées.</p><form data-form="event-submission"><label class="form-field">Nom de l’association<input name="association" required maxlength="100" placeholder="Ex. : votre association"></label><label class="form-field">Titre de l’événement<input name="title" required maxlength="120" placeholder="Un titre clair et accueillant"></label><div class="choice-grid" style="margin-top:0"><label class="form-field">Date<input name="date" type="date" required></label><label class="form-field">Catégorie<select name="category"><option>Culture</option><option>Sport</option><option>Nature</option><option>En famille</option><option>Solidarité</option></select></label></div><label class="form-field">Lieu<input name="place" required maxlength="120" placeholder="Le lieu du rendez-vous"></label><label class="form-field">En quelques mots<textarea name="description" required maxlength="600" placeholder="Que proposez-vous aux habitants ?"></textarea></label><button type="submit" class="button primary" style="margin-top:25px">Prévisualiser l’événement ${icon('arrow-right')}</button><p class="form-note">Dans le futur service, une validation éditoriale pourra précéder la publication.</p></form>`)}
function voiceIntro(){const supported=!!(window.SpeechRecognition||window.webkitSpeechRecognition);contentDialog('RECHERCHE VOCALE','Dites-le simplement.',`<p>${supported?'Vous pouvez dicter votre recherche avec le service vocal de votre navigateur. Le navigateur demandera l’autorisation d’utiliser le microphone. Selon son fonctionnement, l’audio peut être traité par son fournisseur.':'La reconnaissance vocale n’est pas disponible dans ce navigateur. La recherche au clavier vous permet de tester le même parcours.'}</p><div id="voice-status" role="status"></div><div class="modal-actions">${supported?`<button class="button primary" data-action="voice-start">${icon('mic')} Activer le microphone</button>`:''}<button class="button outline" data-action="search">Écrire ma recherche</button></div>`)}
let recognition=null;
function startVoice(){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return;recognition=new SR();recognition.lang='fr-FR';recognition.interimResults=false;recognition.continuous=false;$('#voice-status').innerHTML='<p>À votre écoute… Posez votre question.</p>';const b=$('[data-action=voice-start]');if(b)b.disabled=true;recognition.onresult=e=>{const q=e.results[0][0].transcript;recognition=null;searchModal(q)};recognition.onerror=e=>{const box=$('#voice-status');if(box)box.innerHTML=`<p>${e.error==='not-allowed'?'L’accès au microphone n’est pas autorisé. Vous pouvez écrire votre recherche.':'La dictée n’a pas abouti. Réessayez ou utilisez le clavier.'}</p>`;const b=$('[data-action=voice-start]');if(b)b.disabled=false;recognition=null};recognition.onend=()=>{const b=$('[data-action=voice-start]');if(b){b.disabled=false;const status=$('#voice-status');if(status&&!status.textContent.includes('autorisé')&&!status.textContent.includes('abouti'))status.innerHTML='<p>La dictée est terminée. Vous pouvez réessayer ou écrire votre recherche.</p>'}};try{recognition.start()}catch{toast('Le service vocal est indisponible. Utilisez la recherche écrite.')}}
function exportIcs(id){const e=events.find(e=>e.id===id);if(!e)return;const stamp=`2026${String(e.month).padStart(2,'0')}${e.day}T${e.time.replace(':','')}00`;const ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Meudon Prototype//FR','BEGIN:VEVENT',`UID:meudon-demo-${e.id}@prototype.local`,'DTSTAMP:20261011T120000Z',`DTSTART;TZID=Europe/Paris:${stamp}`,'DURATION:PT1H',`SUMMARY:[DÉMONSTRATION - FICTIF] ${e.title}`,`LOCATION:${e.place}`,'DESCRIPTION:Exemple fictif de la maquette Meudon. Aucune programmation réelle.','END:VEVENT','END:VCALENDAR'].join('\r\n');const url=URL.createObjectURL(new Blob([ics],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`meudon-exemple-${e.id}.ics`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exemple fictif exporté au format calendrier.')}
function updateSaved(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('meudon-events',JSON.stringify(saved))}catch{}$$(`[data-action="save-event"][data-id="${id}"]`).forEach(b=>{b.setAttribute('aria-pressed',String(saved.includes(id)));const e=events.find(x=>x.id===id);b.setAttribute('aria-label',`${saved.includes(id)?'Retirer':'Enregistrer'} ${e.title}`);const span=$('span',b);if(span)span.textContent=saved.includes(id)?'Retirer de mes favoris':'Enregistrer ce rendez-vous'});if($('#saved-count'))$('#saved-count').textContent=`(${saved.length})`;if(state.savedOnly&&$('#agenda-events'))filterAgenda();toast(saved.includes(id)?'Ajouté à vos favoris dans ce navigateur.':'Retiré de vos favoris.')}
function filterButtons(container,val){$$('.chip',container).forEach(b=>{const active=b.dataset.value===val;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))})}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(b.tagName==='A'&&action!=='close-link')e.preventDefault();switch(action){
case 'hero-photo':{const n=Number(b.dataset.id);if(![0,1,2].includes(n))break;if(window.MeudonMotion){window.MeudonMotion.selectPhoto(n)}else{const stage=$('#hero-photo-stage');stage.innerHTML=img(n,'',true);stage.dataset.photo=String(n);syncHeroPhoto(n)}break}
case 'hero-enlarge':{const n=Number($('#hero-photo-stage')?.dataset.photo||0);galleryDialog(n);break}
case 'chapter':{const target=document.getElementById(b.dataset.target);if(target){target.scrollIntoView({behavior:preferences.motion||matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});const title=$('h2',target)||target;title.setAttribute('tabindex','-1');title.focus({preventScroll:true})}break}
case 'mega':megaMenu(b.dataset.menu);break;
case 'close-mega':closeMega(true);break;
case 'choose-district':state.district=Number(b.dataset.id);closeMenu();if(currentRoute==='/quartiers')render();else location.hash='/quartiers';break;
case 'directory-filter':directoryState.category=b.dataset.value;$$('#directory-filters button').forEach(el=>{const active=el.dataset.value===directoryState.category;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active))});updateDirectory();break;
case 'directory-saved':directoryState.savedOnly=!directoryState.savedOnly;b.setAttribute('aria-pressed',String(directoryState.savedOnly));updateDirectory();break;
case 'reset-directory':directoryState.category='Tous';directoryState.query='';directoryState.savedOnly=false;$('#directory-search').value='';$('.directory-saved').setAttribute('aria-pressed','false');$$('#directory-filters button').forEach(el=>{const active=el.dataset.value==='Tous';el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active))});updateDirectory();break;
case 'save-service':saveService(b.dataset.id);break;
case 'portal-detail':portalDetail(b.dataset.id);break;
case 'menu':{closeMega();const opening=$('#mobile-nav').hidden;if(opening){$('#mobile-nav').innerHTML=buildMobileMenu();const menuTop=$('.site-header').getBoundingClientRect().bottom;$('#mobile-nav').style.top=menuTop+'px';$('#mobile-nav').style.maxHeight=`calc(100svh - ${menuTop}px)`;hydrate($('#mobile-nav'))}$('#mobile-nav').hidden=!opening;b.setAttribute('aria-expanded',String(opening));b.setAttribute('aria-label',opening?'Fermer le menu':'Ouvrir le menu');b.innerHTML=icon(opening?'x':'menu');document.body.classList.toggle('menu-open',opening);setMenuInert(opening);if(opening)$('button,a,summary',$('#mobile-nav'))?.focus();break}
case 'close':closeDialog();break;case 'close-link':closeDialog();break;case 'search':searchModal();break;case 'search-example':searchModal(b.dataset.value);break;case 'top':window.scrollTo({top:0,behavior:preferences.motion?'instant':'smooth'});break;
case 'about':contentDialog('PROPOSITION DE REFONTE','Meudon.<br>Une ville, un point d’entrée.',`<p>Cette maquette interactive permet de valider l’identité visuelle, la navigation et les parcours du futur site municipal. Elle ne remplace pas le site officiel de la Ville.</p><h3>Ce que vous pouvez tester</h3><ul><li>Les services organisés autour de « Je veux… »</li><li>Un parcours pour les familles et des entrées par quartier</li><li>L’agenda filtrable, ses favoris et ses fiches</li><li>L’espace associations et la prévisualisation d’un événement</li><li>La galerie photo, la recherche et les réglages de lecture</li></ul><h3>Une expérience à connecter ensuite</h3><p>Les événements sont fictifs. La recherche porte sur les contenus référencés dans cette maquette. Les formulaires ne transmettent rien et les démarches renvoient aux services officiels. Les favoris et préférences sont stockés uniquement dans le navigateur.</p><p>Images compressées, aucun lecteur vidéo automatique, aucun traceur publicitaire et animations désactivables. La conformité RGAA et RGESN n’a pas fait l’objet d’un audit.</p><a class="button primary" href="${official.home}" target="_blank" rel="noopener">Consulter le site officiel ${icon('external')}</a>`);break;
case 'accessibility':contentDialog('À VOTRE RYTHME','Votre confort<br>de lecture.',`<p>Ces réglages sont conservés dans ce navigateur. Le site tient également compte de la préférence système de réduction des animations.</p><label class="setting-row"><div><strong>Réduire les mouvements</strong><span>Désactiver les effets de profondeur et les transitions</span></div><input type="checkbox" data-pref="motion" ${preferences.motion?'checked':''}></label><label class="setting-row"><div><strong>Agrandir les textes</strong><span>Donner plus de place au contenu</span></div><input type="checkbox" data-pref="large" ${preferences.large?'checked':''}></label><label class="setting-row"><div><strong>Renforcer les contrastes</strong><span>Accentuer les textes et les séparations</span></div><input type="checkbox" data-pref="contrast" ${preferences.contrast?'checked':''}></label><div class="modal-actions"><a class="button outline" href="https://app.acce-o.fr/client/meudon" target="_blank" rel="noopener">Contacter la Ville avec Acceo ${icon('external')}</a></div><p class="form-note">Les réglages de confort ne constituent pas une déclaration de conformité. Un audit d’accessibilité restera à réaliser avant mise en service.</p>`);break;
case 'credits':creditsDialog();break;case 'service-detail':serviceDetail(b.dataset.id);break;case 'council':councilDialog();break;case 'project':projectDialog(b.dataset.id);break;case 'event':eventDialog(Number(b.dataset.id));break;case 'save-event':updateSaved(Number(b.dataset.id));break;case 'ical':exportIcs(Number(b.dataset.id));break;
case 'gallery':galleryDialog(Number(b.dataset.id));break;case 'gallery-prev':galleryStep(-1);break;case 'gallery-next':galleryStep(1);break;
case 'home-agenda':{filterButtons(b.parentElement,b.dataset.value);const list=events.filter(x=>b.dataset.value==='Tout'||x.category===b.dataset.value).slice(0,3);$('#home-events').innerHTML=list.map(eventCard).join('');hydrate($('#home-events'));break}
case 'service-filter':state.serviceFilter=b.dataset.value;filterButtons(b.parentElement,state.serviceFilter);filterServices();break;
case 'reset-services':state.serviceFilter='Tout';state.serviceQuery='';$('#service-search').value='';filterButtons($('#service-filters'),'Tout');filterServices();break;
case 'profile':{if(b.dataset.value==='Parent'){location.hash='/famille'}else if(b.dataset.value==='Une association'){location.hash='/associations'}else if(b.dataset.value==='Nouvel arrivant'){location.hash='/quartiers'}else{state.serviceQuery='senior';state.serviceFilter='Tout';$('#service-search').value='senior';filterButtons($('#service-filters'),'Tout');filterServices()}break}
case 'agenda-filter':state.agendaFilter=b.dataset.value;filterButtons(b.parentElement,state.agendaFilter);filterAgenda();break;
case 'month':state.agendaMonth+=Number(b.dataset.delta);state.agendaMonth=Math.max(1,Math.min(12,state.agendaMonth));filterAgenda();break;
case 'saved-filter':state.savedOnly=!state.savedOnly;b.setAttribute('aria-pressed',String(state.savedOnly));filterAgenda();break;
case 'reset-agenda':state.agendaMonth=10;state.agendaFilter='Tout';state.savedOnly=false;Object.assign(agendaExtra,{district:'Tous',organizer:'Tous',audience:'Tous'});$('#main').innerHTML=agendaView();hydrate();filterAgenda();$('#main').focus({preventScroll:true});break;
case 'district':state.district=Number(b.dataset.id);$$('#district-tabs button').forEach((el,i)=>{el.classList.toggle('active',i===state.district);el.setAttribute('aria-pressed',String(i===state.district))});$('#district-content').innerHTML=districtContent();hydrate($('#district-content'));break;
case 'local-place':{const d=districts[state.district];contentDialog(d.name,d.place,`<p>${d.placeNote}</p><p>Retrouvez les coordonnées et les modalités d’accès dans les informations publiées par la Ville.</p><div class="modal-actions"><a class="button primary" href="#/contact" data-action="close-link">Contacter la mairie ${icon('arrow-right')}</a><button class="button outline" data-action="service-detail" data-id="equipement">Les équipements</button></div>`);break}
case 'assoc-filter':state.assocFilter=b.dataset.value;filterButtons(b.parentElement,state.assocFilter);filterAssociations();break;
case 'association-detail':contentDialog('VIE ASSOCIATIVE',b.dataset.value+' à Meudon',`<p>Cette entrée propose de retrouver les associations par envie. La liste nominative doit être alimentée par l’annuaire municipal à jour.</p><p>Aucune association fictive n’a été créée pour la maquette. L’annuaire officiel permet de consulter les structures existantes et leurs coordonnées.</p><div class="modal-actions"><a href="${official.association}" target="_blank" rel="noopener" class="button primary">Consulter l’annuaire officiel ${icon('external')}</a><button class="button outline" data-action="submit-event">Proposer un événement</button></div>`);break;
case 'submit-event':submitEventDialog();break;
case 'family-age':state.age=b.dataset.value;$('#main').innerHTML=familyView();hydrate();$$('[data-action=family-age]').find(x=>x.dataset.value===state.age)?.focus();break;
case 'reset-associations':associationState.query='';state.assocFilter='Tout';$('#association-search').value='';filterButtons($('#assoc-filters'),'Tout');filterAssociations();break;
case 'age':state.age=b.dataset.value;$('#wizard-content').innerHTML=wizardContent();hydrate($('#wizard-content'));$('[data-action=wizard-next]').focus({preventScroll:true});break;
case 'activity':state.activity=b.dataset.value;$('#wizard-content').innerHTML=wizardContent();hydrate($('#wizard-content'));$('[data-action=wizard-next]').focus({preventScroll:true});break;
case 'wizard-next':if((state.wizardStep===1&&state.age)||(state.wizardStep===2&&state.activity)){state.wizardStep++;$('#main').innerHTML=familyView();hydrate();$('.wizard-content').setAttribute('tabindex','-1');$('.wizard-content').focus({preventScroll:true});$('.wizard-content').scrollIntoView({behavior:preferences.motion?'instant':'smooth',block:'center'})}break;
case 'wizard-back':state.wizardStep=Math.max(1,state.wizardStep-1);$('#main').innerHTML=familyView();hydrate();$('.wizard-content').setAttribute('tabindex','-1');$('.wizard-content').focus({preventScroll:true});break;
case 'voice-intro':voiceIntro();break;case 'voice-start':startVoice();break;
}});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const data=new FormData(form);if(form.dataset.form==='hero-search'){searchModal(data.get('query')||'');}else if(form.dataset.form==='search'){runSearch(data.get('query')||'');}else if(form.dataset.form==='event-submission'){const title=esc(data.get('title')),desc=esc(data.get('description'));contentDialog('APERÇU · NON TRANSMIS','Votre rendez-vous<br>prend forme.',`<div class="submission-preview"><span class="eyebrow">${esc(data.get('category'))} · BROUILLON LOCAL</span><h3>${title}</h3><p>${esc(data.get('date'))} · ${esc(data.get('place'))}</p><p>${desc}</p><strong style="font-size:12px">Proposé par ${esc(data.get('association'))}</strong></div><p style="margin-top:25px">Cet aperçu termine le parcours de démonstration. Aucune proposition n’a été envoyée et aucune information n’a été enregistrée.</p><button class="button primary" data-action="close">Terminer la démonstration ${icon('check')}</button>`)}});
document.addEventListener('input',e=>{if(e.target.id==='association-search'){associationState.query=e.target.value;filterAssociations()}if(e.target.id==='directory-search'){directoryState.query=e.target.value;updateDirectory()}if(e.target.id==='service-search'){state.serviceQuery=e.target.value;filterServices()}});
document.addEventListener('change',e=>{if(e.target.id==='agenda-district'){agendaExtra.district=e.target.value;filterAgenda()}if(e.target.id==='agenda-organizer'){agendaExtra.organizer=e.target.value;filterAgenda()}if(e.target.id==='agenda-audience'){agendaExtra.audience=e.target.value;filterAgenda()}if(e.target.id==='directory-sort'){directoryState.sort=e.target.value;updateDirectory()}if(e.target.dataset.pref){preferences[e.target.dataset.pref]=e.target.checked;try{localStorage.setItem('meudon-preferences',JSON.stringify(preferences))}catch{}applyPrefs();if(preferences.motion)finishCounters();else animateCounters()}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
$('#dialog').addEventListener('close',()=>{document.body.classList.remove('modal-open');if(recognition){recognition.abort();recognition=null}});
document.addEventListener('keydown',e=>{const navTrigger=e.target.closest('[data-action=mega]');if(navTrigger&&e.key==='ArrowDown'){e.preventDefault();if($('#mega-panel').hidden||$('#mega-panel').dataset.menu!==navTrigger.dataset.menu)megaMenu(navTrigger.dataset.menu);$('.mega-link',$('#mega-panel'))?.focus()}if(e.key==='Escape'){const megaOpen=!$('#mega-panel').hidden;closeMega(megaOpen);if(!$('#mobile-nav').hidden){closeMenu();$('[data-action=menu]').focus()}}if($('#dialog').open&&$('#dialog').classList.contains('lightbox')){if(e.key==='ArrowRight')galleryStep(1);if(e.key==='ArrowLeft')galleryStep(-1)}if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();searchModal()}});
$('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus({preventScroll:true});$('#main').scrollIntoView({behavior:'instant'});});

function syncNavigation(route){const group=route.startsWith('/association')||route==='/espace-associations'?'associations':route==='/famille'?'famille':['/activites','/agenda','/galerie'].includes(route)||route.startsWith('/album/')?'sortir':route==='/quartiers'?'quartiers':['/mairie','/decouvrir','/participer','/contact','/reseaux'].includes(route)?'ville':route.startsWith('/service')?'quotidien':'';$$('.desktop-nav > button,.desktop-nav > a').forEach(el=>{const on=el.dataset.menu===group;el.classList.toggle('nav-current',on);if(on)el.setAttribute('aria-current','true');else el.removeAttribute('aria-current')})}
$('#nav-backdrop').addEventListener('click',()=>closeMega(true));
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.getAttribute('href')?.startsWith('#/')&&!a.dataset.action){closeMega();closeMenu()}if(a?.target==='_blank'){closeMega();closeMenu()}});
document.addEventListener('focusin',e=>{if(!$('#mega-panel').hidden&&!$('.site-header').contains(e.target))closeMega()});
matchMedia('(max-width:1240px)').addEventListener('change',()=>closeMenu());
const motionQuery=matchMedia('(prefers-reduced-motion: reduce)');motionQuery.addEventListener('change',()=>{if(motionQuery.matches)finishCounters();else animateCounters()});
$('#footer-socials').innerHTML='<span class="eyebrow">SUIVRE MEUDON</span>'+socialLinks('footer-network');

function setMenuInert(on){for(const selector of ['#main','.site-footer','.assistant-launch','.prototype-bar','.brand','.desktop-nav','.header-actions > a','.header-actions > button[data-action=search]']){const el=$(selector);if(el)el.inert=on}}
document.addEventListener('keydown',e=>{if(e.key!=='Tab'||$('#mobile-nav').hidden)return;const focusables=[$('[data-action=menu]'),...$$('button,a,summary',$('#mobile-nav'))].filter(el=>!el.disabled&&el.getClientRects().length);const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}});
// Navigation and first render are installed by usability-v6.js after feature modules.
hydrate();
